import * as T from 'three';import {componentDefaults} from '../scene-components.js';import {createGameCamera,selectGameCamera,previewGameCamera} from '../game-camera.js';import {CameraViewRendering} from '../camera-view-rendering.js';import {BloomRendering} from '../bloom-rendering.js';import {ViewportPresentation,createViewportToolbar} from '../viewport-presentation.js';
export async function cameraViews(){let checks=0;const check=(v,m)=>{if(!v)throw Error(m);checks++;},objects=[],groups=new Map(),scene=new T.Scene();scene.background=new T.Color('black');
for(const [id,x,color]of [['A',-4,'#ff0000'],['B',4,'#00ff00']]){const p={...componentDefaults('Camera'),main:id==='A',projection:'orthographic',orthographicSize:1,screenOutput:true,screenRegion:id==='A'?'left':'right'},g=new T.Group(),camera=createGameCamera(p);camera.position.z=5;g.position.x=x;g.add(camera);g.userData.gameCamera=camera;scene.add(g);groups.set(id,g);objects.push({id,name:'Camera '+id,visible:true,components:[{id:'camera',type:'Camera',properties:p}]});const mesh=new T.Mesh(new T.PlaneGeometry(4,3),new T.MeshBasicMaterial({color,toneMapped:false}));mesh.position.x=x;scene.add(mesh);}
const canvas=document.createElement('canvas'),r=new T.WebGLRenderer({canvas,preserveDrawingBuffer:true}),views=new CameraViewRendering(()=>new BloomRendering());document.body.append(canvas);r.setPixelRatio(1.5);r.setSize(161,101);const current=id=>groups.get(id),camera=()=>selectGameCamera(objects,{width:161,height:101},null,current);function color(renderer,x,y,expected){const gl=renderer.getContext(),pixel=new Uint8Array(4);gl.readPixels(x,renderer.domElement.height-1-y,1,1,gl.RGBA,gl.UNSIGNED_BYTE,pixel);check([...pixel].slice(0,3).every((v,i)=>Math.abs(v-expected[i])<6),JSON.stringify({pixel:[...pixel],expected,x,y}));}
const hosts=[],renderers=[];try{views.render(r,scene,camera(),objects,()=>{},()=>{});color(r,50,75,[255,0,0]);color(r,190,75,[0,255,0]);color(r,120,75,[255,0,0]);color(r,121,75,[0,255,0]);objects[0].components[0].properties.screenRegion='full';objects[1].components[0].properties.screenRegion='bottomRight';views.render(r,scene,camera(),objects,()=>{},()=>{});color(r,30,30,[255,0,0]);color(r,210,125,[0,255,0]);
objects[1].components[0].properties.screenRegion='right';objects[0].components[0].properties.screenRegion='left';const volume={id:'post',visible:true,components:[{id:'post',type:'PostProcessVolume',properties:{...componentDefaults('PostProcessVolume'),bloomEnabled:false,bloomStrength:0,antiAliasing:'taa',motionBlurEnabled:true}}]};for(let time=0;time<3;time++){scene.userData.hbMaterialTime=time/120;views.render(r,scene,camera(),[...objects,volume],()=>{},()=>{});}for(const [x,channel]of [[50,0],[190,1]]){const gl=r.getContext(),pixel=new Uint8Array(4);gl.readPixels(x,75,1,1,gl.RGBA,gl.UNSIGNED_BYTE,pixel);check(pixel[channel]>150&&pixel[1-channel]<20,'camera post history color isolation');}let action=0;for(const [index,id]of ['A','B'].entries()){const host=document.createElement('div');document.body.append(host);hosts.push(host);const c=document.createElement('canvas');host.append(c);const renderer=new T.WebGLRenderer({canvas:c,preserveDrawingBuffer:true});renderer.setSize(80,100);renderers.push(renderer);let target=id,preview=null;const controls={getSettings:()=>({speed:1,speedScalar:1,sensitivity:.001,fastMultiplier:4,scrollZoomSpeed:1,flightMode:'rmb'}),setSettings(){},saveBookmark(){},restoreBookmark(){}},presentation=new ViewportPresentation(),toolbar=createViewportToolbar(host,{presentation,controls:()=>controls,camera:()=>preview||new T.PerspectiveCamera(),direction:()=> '3d',onDirection(){},onAction:key=>{if(key==='camera-preview')action++;},cameraTargets:{options:()=>objects.map(o=>[o.id,o.name]),value:()=>target,onChange:value=>target=value}});preview=previewGameCamera(objects,{width:80,height:100},target,current,preview);renderer.render(scene,preview);color(renderer,40,50,index?[0,255,0]:[255,0,0]);const select=toolbar.element.querySelector('[aria-label="미리보기 카메라"]');check(select.value===id,'independent target');select.value=index?'A':'B';select.dispatchEvent(new Event('change'));toolbar.sync();check(target===(index?'A':'B'),'target change');check(toolbar.element.querySelector('[aria-label=시야각]').disabled,'authored lens is edited in component inspector');toolbar.element.querySelector('[data-viewport-action="camera-preview"]').click();target='removed';toolbar.sync();check(select.selectedOptions[0].textContent==='카메라 사용 불가','removed camera indication');presentation.dispose();}check(action===2,'preview action in both toolbars');check(renderers[0].getContext()!==renderers[1].getContext(),'simultaneous independent viewport surfaces');views.dispose();check(views.views.size===0,'closed views release post histories');return {passed:true,checks,split:true,pip:true,fractionalDPR:1.5,editorIndependentPreviews:2,toolbarTargetsAndOpen:true,scope:'Isolated actual WebGL and production toolbar/preview functions; full editor shell not loaded because protected player module is forbidden'};
}finally{views.dispose();for(const renderer of [...renderers,r]){renderer.dispose();renderer.forceContextLoss();renderer.domElement.remove();}hosts.forEach(h=>h.remove());scene.traverse(n=>{n.geometry?.dispose();n.material?.dispose();});}}
